import{_ as t,o as a,c as d,a0 as o}from"./chunks/framework.BRO9oVoP.js";const u=JSON.parse('{"title":"Storage (server-storage)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/storage/index.md","filePath":"reference/storage/index.md"}'),s={name:"reference/storage/index.md"};function i(r,e,n,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="storage-server-storage" tabindex="-1">Storage (server-storage) <a class="header-anchor" href="#storage-server-storage" aria-label="Permalink to &quot;Storage (server-storage)&quot;">​</a></h1><p>The Storage service manages file and object storage, backed by MinIO (S3-compatible) or, without a MinIO connection, the local filesystem. It provides bucket and file CRUD operations with streaming support.</p><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># From the repo root: build every workspace, then start the HTTP server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/server-storage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Database migrations: run | revert | status | generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/server-storage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/privateaim/hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> storage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><code>start</code> creates the database when it does not exist and applies pending migrations before it serves.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Database</strong> — MySQL, PostgreSQL, or SQLite</li><li><strong>Authup</strong> — OAuth2 identity provider</li><li><strong>MinIO</strong> (optional) — S3-compatible object storage; without it files go to the local filesystem (<code>STORAGE_PATH</code>), which several replicas do not share and a container loses unless the path is a volume</li><li><strong>RabbitMQ</strong> (optional) — AMQP message bus; without it no analysis bucket is created, because server-core sends bucket commands over the bus</li><li><strong>Redis</strong> (optional) — realtime entity events</li></ul><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><h3 id="service-specific" tabindex="-1">Service-Specific <a class="header-anchor" href="#service-specific" aria-label="Permalink to &quot;Service-Specific&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PUBLIC_URL</code></td><td><code>http://localhost:&lt;PORT&gt;</code></td><td>Public URL of this service</td></tr><tr><td><code>MINIO_CONNECTION_STRING</code></td><td>—</td><td>MinIO or S3 endpoint as <code>http(s)://&lt;access-key&gt;:&lt;secret-key&gt;@&lt;host&gt;:&lt;port&gt;</code>; <code>https</code> enables TLS. Port is required, nothing may follow it (no trailing <code>/</code>), and key and secret may contain only letters, digits and <code>_</code>. A malformed value stops the start (<code>Invalid MINIO_CONNECTION_STRING format.</code>).</td></tr><tr><td><code>STORAGE_PATH</code></td><td><code>&lt;cwd&gt;/writable/storage</code></td><td>Directory for files when <code>MINIO_CONNECTION_STRING</code> is unset</td></tr><tr><td><code>CAPABILITY_CLIENT_ID</code></td><td><code>CLIENT_ID</code></td><td>The Authup client (id, or name in <code>REALM</code>) whose capability-token exchanges are accepted: the client server-core authenticates as. A token another client exchanged is refused (401). A name is looked up once through Authup, which needs <code>client_read</code> for storage&#39;s own client; an id needs no lookup.</td></tr></tbody></table><h3 id="inherited" tabindex="-1">Inherited <a class="header-anchor" href="#inherited" aria-label="Permalink to &quot;Inherited&quot;">​</a></h3><p>See <a href="/reference/#shared-configuration">Shared Configuration</a> and <a href="/reference/#database-configuration">Database Configuration</a>.</p><h2 id="key-endpoints" tabindex="-1">Key Endpoints <a class="header-anchor" href="#key-endpoints" aria-label="Permalink to &quot;Key Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code>/<code>HEAD</code></td><td><code>/livez</code>, <code>/readyz</code></td><td>Anonymous liveness and readiness probes (see <a href="/guide/deployment/configuration.html#health-endpoints">Health endpoints</a>)</td></tr><tr><td><code>GET</code></td><td><code>/buckets</code></td><td>List buckets</td></tr><tr><td><code>POST</code></td><td><code>/buckets</code></td><td>Create bucket (no <code>refId</code>, see below)</td></tr><tr><td><code>GET</code></td><td><code>/buckets/:id</code></td><td>Get bucket</td></tr><tr><td><code>POST</code></td><td><code>/buckets/:id</code></td><td>Update bucket</td></tr><tr><td><code>DELETE</code></td><td><code>/buckets/:id</code></td><td>Delete bucket</td></tr><tr><td><code>POST</code></td><td><code>/buckets/:id/clear</code></td><td>Empty a bucket — remove every file, keep the bucket</td></tr><tr><td><code>POST</code></td><td><code>/buckets/:id/upload</code></td><td>Upload files into a bucket</td></tr><tr><td><code>GET</code></td><td><code>/buckets/:id/stream</code></td><td>Stream the bucket contents as a tar</td></tr><tr><td><code>GET</code></td><td><code>/bucket-files</code></td><td>List files</td></tr><tr><td><code>GET</code></td><td><code>/bucket-files/:id</code></td><td>Get file</td></tr><tr><td><code>DELETE</code></td><td><code>/bucket-files/:id</code></td><td>Delete file</td></tr><tr><td><code>GET</code></td><td><code>/bucket-files/:id/stream</code></td><td>Stream file contents</td></tr><tr><td><code>GET</code></td><td><code>/docs</code></td><td>Swagger/OpenAPI documentation</td></tr></tbody></table><p>A bucket with a <code>refType</code> <strong>and</strong> <code>refId</code> is unique per <code>(refType, refId, name)</code>. Only the service owning the referenced resource sets a <code>refId</code>, through the <code>create</code> bus command; <code>POST /buckets</code> with a <code>refId</code> answers 400, since storage cannot check who owns the referenced resource. A repeated bus create of a triple that already exists in the same realm answers with the existing bucket instead of a second one; the same triple in another realm fails. Buckets without a ref are not deduplicated: they may share a name.</p><p>A bucket records its creator (<code>actorId</code>/<code>actorType</code>): for <code>POST /buckets</code> the authenticated identity (an actor in the body is ignored), for a bus create the actor named in the command. The creator may update, clear and delete the bucket, and delete its files, without <code>bucket_update</code>/<code>bucket_delete</code>; everyone else needs the permission and realm access. Buckets without a recorded creator are not backfilled, so only permission holders can manage them.</p><p>Uploading (<code>POST /buckets/:id/upload</code>) into a bucket <strong>without</strong> a <code>refId</code> requires being its creator, or <code>bucket_update</code> with realm access; anyone else gets 403 before a file is stored. A bucket <strong>with</strong> a <code>refId</code> (e.g. an analysis bucket) accepts uploads from any authenticated caller, because its legitimate uploaders span realms and storage cannot evaluate the referencing service&#39;s permissions: the owning service checks each upload when it registers it (see <a href="/guide/deployment/configuration.html#writing-analysis-buckets-and-files-requires-analysis-update">Writing analysis buckets and files</a>).</p><h2 id="capability-tokens" tabindex="-1">Capability Tokens <a class="header-anchor" href="#capability-tokens" aria-label="Permalink to &quot;Capability Tokens&quot;">​</a></h2><p>Besides a login, server-storage accepts an Authup <strong>capability token</strong> (<code>kind: capability_token</code>, audience <code>storage</code>) minted by server-core through <a href="/reference/core/#storage-capability-tokens"><code>POST /analyses/:id/storage/token</code></a>. It is verified locally (signature against Authup&#39;s <code>/jwks</code>, <code>aud</code>, <code>kind</code>, <code>exp</code>) and grants only the actions on the resources in its <code>cap</code> claim. Only a token exchanged by <code>CAPABILITY_CLIENT_ID</code> (its <code>act.sub</code>) is accepted, as Authup lets every client with a <code>storage</code> exchange capability mint one. A capability request carries no identity: every route not listed below answers it 401.</p><table tabindex="0"><thead><tr><th>Where</th><th>Routes</th></tr></thead><tbody><tr><td><code>Authorization: Bearer</code> header</td><td><code>GET /buckets</code>, <code>GET /buckets/:id</code>, <code>POST /buckets/:id/upload</code>, <code>GET /bucket-files</code>, <code>GET /bucket-files/:id</code>, <code>DELETE /bucket-files/:id</code></td></tr><tr><td><code>?dt=&lt;token&gt;</code> query parameter</td><td><code>GET /buckets/:id/stream</code>, <code>GET /bucket-files/:id/stream</code> only, and only for a token living at most 60 s (<code>exp - iat</code>)</td></tr></tbody></table><p>Bucket create, update, delete and clear are login only. A token in the query is never accepted on any other route, and a query token that lives longer than 60 s is refused (401). Only one <code>dt</code> is allowed.</p><p><code>cap</code> entries are <code>type:id:actions</code>:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Covers</th></tr></thead><tbody><tr><td><code>bucket:&lt;id&gt;:read</code></td><td>The bucket, its tar stream and every file in it</td></tr><tr><td><code>bucket:&lt;id&gt;:write</code></td><td>Uploads into the bucket</td></tr><tr><td><code>bucket:&lt;id&gt;:delete</code></td><td>Deleting files of the bucket</td></tr><tr><td><code>bucketFile:&lt;id&gt;:read</code> / <code>:delete</code></td><td>That one file only</td></tr></tbody></table><p>Listings are narrowed to the covered buckets and files: a filter on another bucket returns nothing. Stream responses send <code>Referrer-Policy: no-referrer</code> so a token in the URL does not leak, and the query string is never logged. server-core remains the authority on who may upload (it judges each file when it registers it).</p><h2 id="response-shapes" tabindex="-1">Response Shapes <a class="header-anchor" href="#response-shapes" aria-label="Permalink to &quot;Response Shapes&quot;">​</a></h2><p>Every bucket and bucket-file endpoint answers with a <code>{ data, meta }</code> envelope — the record (or the record array) under <code>data</code>. Query-capable <code>GET</code>s advertise the endpoint&#39;s queryable vocabulary at <code>meta.schema</code>; mutations carry <code>meta: {}</code>.</p><p>Three surfaces stay outside the record envelope:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Shape</th></tr></thead><tbody><tr><td><code>GET /</code></td><td><code>{ version, timestamp }</code> — service metadata, flat</td></tr><tr><td><code>GET /buckets/:id/stream</code>, <code>GET /bucket-files/:id/stream</code></td><td>flat binary streams with attachment headers</td></tr><tr><td><code>POST /buckets/:id/upload</code></td><td>a <strong>collection</strong> (<code>{ data: files, meta: { total } }</code>), because it uploads many files — no <code>schema</code></td></tr></tbody></table><p>See <a href="/guide/development/api.html#response-shapes">API Reference</a> for the full contract and the <code>meta.schema</code> reading rules.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><strong>BucketEntity</strong> / <strong>BucketFileEntity</strong> — TypeORM entities tracking storage metadata</li><li><strong>StorageModule</strong> — registers the storage adapter in the DI container: a MinIO client when <code>MINIO_CONNECTION_STRING</code> is set, else the filesystem adapter on <code>STORAGE_PATH</code></li><li><strong>BucketComponent</strong> — AMQP consumer for asynchronous bucket operations: <code>create</code>, <code>delete</code> and <code>clear</code> (removes every object and bucket-file row but keeps the bucket, emitting <code>clearingStarted</code> / <code>clearingFinished</code> / <code>clearingFailed</code>)</li><li><strong>Subscribers</strong> — publish domain events on bucket/file changes</li></ul>`,31)])])}const k=t(s,[["render",i]]);export{u as __pageData,k as default};
